local AlambicStillMaker = {}
local PRODUCTS = {
    simple_copper_alambic = { name = "Preprosta bakrena alembik", copperCost = 2, time = 4, cost = 50, science = 22, happiness = 1, description = "Preprosta bakrena alembik za destilacijo." },
    tin_luted_alambic = { name = "Kositrnozaprta alembik", copperCost = 2, tinCost = 1, time = 6, cost = 140, science = 35, happiness = 2, prestige = 2, description = "Kositrnozaprta alembik za trgovce." },
    silver_cooled_alambic = { name = "Srebrnohlajena alembik", copperCost = 2, silverCost = 1, tinCost = 1, time = 9, cost = 340, science = 50, happiness = 2, prestige = 6, description = "Srebrnohlajena alembik za plemiče." },
    gold_trimmed_alambic = { name = "Zlatookrasna alembik", copperCost = 2, goldCost = 1, silverCost = 1, tinCost = 1, time = 13, cost = 800, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasna alembik za visoke plemiče." },
    jewel_valve_alambic = { name = "Draguljnoventilna alembik", copperCost = 2, goldCost = 2, silverCost = 1, tinCost = 1, jewelCost = 1, time = 17, cost = 1800, science = 80, happiness = 5, prestige = 27, description = "Alembik z draguljnim ventilom za visoko plemstvo." },
    royal_grand_alambic = { name = "Kraljevski veliki alembik", copperCost = 3, goldCost = 3, silverCost = 2, tinCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4100, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska alembik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    alambic_workshop = { name = "Alembična delavnica", cost = { gold = 240, wood = 100, stone = 120, copper = 6 }, upkeep = 5, qualityBonus = 5 },
    distillery_loft = { name = "Destilatorska podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, tin = 6 }, upkeep = 20, qualityBonus = 18 },
    master_coppersmith_atelier = { name = "Mojstrski bakrokleparski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_alambic_palace = { name = "Kraljevska alembična palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
AlambicStillMaker.copperStock = 14; AlambicStillMaker.tinStock = 10; AlambicStillMaker.silverStock = 6; AlambicStillMaker.goldStock = 6; AlambicStillMaker.jewelStock = 4; AlambicStillMaker.pearlStock = 4
AlambicStillMaker.productStock = {}; AlambicStillMaker.buildings = {}; AlambicStillMaker.maker = nil; AlambicStillMaker.activeMaking = {}; AlambicStillMaker.totalProducts = 0; AlambicStillMaker.dayTimer = 0
function AlambicStillMaker.init() AlambicStillMaker.copperStock=14; AlambicStillMaker.tinStock=10; AlambicStillMaker.silverStock=6; AlambicStillMaker.goldStock=6; AlambicStillMaker.jewelStock=4; AlambicStillMaker.pearlStock=4; AlambicStillMaker.productStock={}; AlambicStillMaker.buildings={}; AlambicStillMaker.maker=nil; AlambicStillMaker.activeMaking={}; AlambicStillMaker.totalProducts=0; AlambicStillMaker.dayTimer=0; print("[AlambicStillMaker] Royal Alambic Still Maker System initialized (6 products, 4 buildings)") end
function AlambicStillMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AlambicStillMaker.maker={name=n or ("Alembikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Alembikar najet: %s (spretnost: %d)",AlambicStillMaker.maker.name,s),"success") end; return true end
function AlambicStillMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AlambicStillMaker.build(id) local ok,e=AlambicStillMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AlambicStillMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AlambicStillMaker.getQualityBonus() local b=0; for _,bd in ipairs(AlambicStillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AlambicStillMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.copperCost and AlambicStillMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.tinCost and AlambicStillMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.silverCost and AlambicStillMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AlambicStillMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AlambicStillMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AlambicStillMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AlambicStillMaker.buildings==0 then return false,"Potrebna alembična delavnica" end; if not AlambicStillMaker.maker then return false,"Potreben alembikar" end; return true end
function AlambicStillMaker.make(pt,qty) qty=qty or 1; local ok,e=AlambicStillMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.copperCost then AlambicStillMaker.copperStock=AlambicStillMaker.copperStock-d.copperCost*qty end; if d.tinCost then AlambicStillMaker.tinStock=AlambicStillMaker.tinStock-d.tinCost*qty end; if d.silverCost then AlambicStillMaker.silverStock=AlambicStillMaker.silverStock-d.silverCost*qty end; if d.goldCost then AlambicStillMaker.goldStock=AlambicStillMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AlambicStillMaker.jewelStock=AlambicStillMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AlambicStillMaker.pearlStock=AlambicStillMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AlambicStillMaker.maker then t=math.max(1,t-math.floor(AlambicStillMaker.maker.skill/13)) end; table.insert(AlambicStillMaker.activeMaking,{id="alambic_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AlambicStillMaker.completeMaking(m) local q=1.0+(AlambicStillMaker.getQualityBonus()/100); if AlambicStillMaker.maker then q=q+(AlambicStillMaker.maker.skill/150) end; q=math.min(2.4,q); AlambicStillMaker.productStock[m.productType]=(AlambicStillMaker.productStock[m.productType] or 0)+m.quantity; AlambicStillMaker.totalProducts=AlambicStillMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AlambicStillMaker.maker then AlambicStillMaker.maker.itemsMade=AlambicStillMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AlambicStillMaker.maker.skill=math.min(100,AlambicStillMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Alembik izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"alambic.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function AlambicStillMaker.update(dt) if not _G.state then return end; AlambicStillMaker.dayTimer=AlambicStillMaker.dayTimer+dt; if AlambicStillMaker.dayTimer>=30 then AlambicStillMaker.dayTimer=0; for i=#AlambicStillMaker.activeMaking,1,-1 do local m=AlambicStillMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AlambicStillMaker.completeMaking(m); table.remove(AlambicStillMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AlambicStillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AlambicStillMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AlambicStillMaker.getStats() return {copperStock=AlambicStillMaker.copperStock,tinStock=AlambicStillMaker.tinStock,silverStock=AlambicStillMaker.silverStock,goldStock=AlambicStillMaker.goldStock,jewelStock=AlambicStillMaker.jewelStock,pearlStock=AlambicStillMaker.pearlStock,productStock=AlambicStillMaker.productStock,numBuildings=#AlambicStillMaker.buildings,hasMaker=AlambicStillMaker.maker~=nil,makerName=AlambicStillMaker.maker and AlambicStillMaker.maker.name or "—",makerSkill=AlambicStillMaker.maker and AlambicStillMaker.maker.skill or 0,activeMaking=#AlambicStillMaker.activeMaking,totalProducts=AlambicStillMaker.totalProducts} end
return AlambicStillMaker
